import heapq


def _dependency_solver(data, name_order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    roots = data["roots"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    choices = {}
    for name in names:
        choices[name] = [None] + [
            row["version"] for row in packages[name]
            if row["version"] not in blocked.get(name, [])
            and (name not in pins or row["version"] == pins[name])
        ]

    best_vector = None
    best_selected = None
    row_by_version = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }

    for values in product(*(choices[name] for name in names)):
        selected = {name: value for name, value in zip(names, values)
                    if value is not None}
        if any(name not in selected or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        closure = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            if name not in selected:
                valid = False
                break
            closure.add(name)
            deps = [dep for dep in row_by_version[name][selected[name]].get("deps", [])
                    if not dep.get("feature") or dep.get("feature") in features]
            edges[name] = []
            for dep in deps:
                other = dep["name"]
                edges[name].append(other)
                if (other not in selected or
                        not dep["min"] <= selected[other] <= dep["max"]):
                    valid = False
                    break
                pending.append(other)
        if not valid or closure != set(selected):
            continue

        active, finished = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in closure):
            continue

        vector = tuple(selected.get(name, -1) for name in names)
        if (best_vector is None or
                (vector > best_vector if maximize else vector < best_vector)):
            best_vector = vector
            best_selected = selected

    if best_selected is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_selected}


def _build_dependency_solver(name_order, maximize):
    return lambda data: _dependency_solver(data, name_order, maximize)


def _round(numerator, mode):
    quotient, remainder = divmod(numerator, 10000)
    if mode == "half_up" and 2 * remainder >= 10000:
        quotient += 1
    return quotient


def _component_06(data):
    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), data["rounding"])
        tax = _round(raw * event.get("tax_bp", 0), data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        id_set = set(ids)
        if id_set & blocked or not mandatory.issubset(id_set):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, change in sorted(events):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids > best_ids):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


